import gurobipy as gp
from gurobipy import GRB
suppliers = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10']
customers = ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10']
demand = {'C1': 45, 'C2': 23, 'C3': 94, 'C4': 92, 'C5': 57, 'C6': 52, 'C7': 23, 'C8': 99, 'C9': 99, 'C10': 77}
supply_capacity = {'S1': 127, 'S2': 236, 'S3': 168, 'S4': 115, 'S5': 280, 'S6': 179, 'S7': 135, 'S8': 263, 'S9': 283, 'S10': 476}
cost = {'S1': {'C1': 2077.058672521021, 'C2': 0.0, 'C3': 54.33526480458508, 'C4': 0.0, 'C5': 0.0, 'C6': 36.17284629162332, 'C7': 0.0, 'C8': 0.0, 'C9': 169.33026926588778, 'C10': 0.0}, 'S2': {'C1': 2077.058672521021, 'C2': 0.0, 'C3': 1141.0405608962865, 'C4': 0.0, 'C5': 0.0, 'C6': 651.1112332492198, 'C7': 0.0, 'C8': 0.0, 'C9': 8.063346155518467, 'C10': 0.0}, 'S3': {'C1': 79.9210295982608, 'C2': 474.24509131006675, 'C3': 1477.0676289106607, 'C4': 22.583099586193658, 'C5': 474.24509131006675, 'C6': 41.106596962251096, 'C7': 474.24509131006675, 'C8': 474.24509131006675, 'C9': 624.162539502301, 'C10': 474.24509131006675}, 'S4': {'C1': 1659.336929105112, 'C2': 57.20541468776147, 'C3': 186.1519048103841, 'C4': 1201.3137084429907, 'C5': 1029.6974643797064, 'C6': 41.82210594495074, 'C7': 57.20541468776147, 'C8': 1201.3137084429907, 'C9': 884.5633870657458, 'C10': 1029.6974643797064}, 'S5': {'C1': 1297.2567040858307, 'C2': 77.76629131320436, 'C3': 24.26760227579214, 'C4': 1399.7932436376784, 'C5': 77.76629131320436, 'C6': 53.91161728496604, 'C7': 1399.7932436376784, 'C8': 77.76629131320436, 'C9': 1255.115148013589, 'C10': 1399.7932436376784}, 'S6': {'C1': 1998.9090658724567, 'C2': 985.3165435695341, 'C3': 2.8541686885814643, 'C4': 1149.53596749779, 'C5': 985.3165435695341, 'C6': 730.6923647662475, 'C7': 54.73980797608523, 'C8': 985.3165435695341, 'C9': 46.803102206463265, 'C10': 1149.53596749779}, 'S7': {'C1': 1780.3360050180179, 'C2': 0.0, 'C3': 1141.0405608962865, 'C4': 0.0, 'C5': 0.0, 'C6': 36.17284629162332, 'C7': 0.0, 'C8': 0.0, 'C9': 8.063346155518467, 'C10': 0.0}, 'S8': {'C1': 75.40935896233042, 'C2': 1338.1987290721909, 'C3': 21.391345987195333, 'C4': 74.34437383734394, 'C5': 74.34437383734394, 'C6': 937.3506239061463, 'C7': 1338.1987290721909, 'C8': 1338.1987290721909, 'C9': 1392.1186581383768, 'C10': 1338.1987290721909}, 'S9': {'C1': 98.90755583433433, 'C2': 0.0, 'C3': 978.0347664825314, 'C4': 0.0, 'C5': 0.0, 'C6': 651.1112332492198, 'C7': 0.0, 'C8': 0.0, 'C9': 169.33026926588778, 'C10': 0.0}, 'S10': {'C1': 2077.058672521021, 'C2': 0.0, 'C3': 54.33526480458508, 'C4': 0.0, 'C5': 0.0, 'C6': 36.17284629162332, 'C7': 0.0, 'C8': 0.0, 'C9': 145.1402307993324, 'C10': 0.0}}
for i in suppliers:
    if i not in cost:
        raise ValueError(f'Missing cost data for supplier {i}')
    for j in customers:
        if j not in cost[i]:
            raise ValueError(f'Missing cost data for supplier {i}, customer {j}')
for j in customers:
    if j not in demand:
        raise ValueError(f'Missing demand data for customer {j}')
for i in suppliers:
    if i not in supply_capacity:
        raise ValueError(f'Missing supply capacity data for supplier {i}')
m = gp.Model('Logistics_Transportation')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[i][j] * x[i, j] for i in suppliers for j in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for i in suppliers)) >= demand[j] for j in customers), name='')
m.addConstrs((gp.quicksum((x[i, j] for j in customers)) <= supply_capacity[i] for i in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for variable in m.getVars():
        print(f'{variable.VarName}: {variable.X}')
else:
    print(f'Solver status: {m.Status}')